import { createSlice } from "@reduxjs/toolkit";
import axios from "../../utils/axios";
import { dispatch } from "../store";

// ----------------------------------------------------------------------

const REMESAS_BASE = "/api/v1/remesas";

const initialState = {
  isLoading: false,
  error: null,

  countries: [],
  currenciesByCountry: {}, // { [countryCode]: [currencies] }
  statesByCountry: {}, // { [countryCode]: [states] }
  citiesByState: {}, // { [stateId]: [cities] }
  citiesByCountry: {}, // { [countryCode]: [cities] }

  genders: [],
  typeDocs: [],
  relationships: [],
  purposes: [],
  maritals: [],
  typeBanks: [],
  typeSents: [],
  calcSents: [],
};

const slice = createSlice({
  name: "remesas",
  initialState,
  reducers: {
    // START LOADING
    startLoading(state) {
      state.isLoading = true;
    },

    // STOP LOADING
    stopLoading(state) {
      state.isLoading = false;
    },

    // HAS ERROR
    hasError(state, action) {
      state.isLoading = false;
      state.error = action.payload;
    },

    // COUNTRIES
    getCountriesSuccess(state, action) {
      state.isLoading = false;
      state.countries = action.payload || [];
    },

    // CURRENCIES BY COUNTRY
    getCurrenciesByCountrySuccess(state, action) {
      state.isLoading = false;
      const { countryCode, data } = action.payload;
      state.currenciesByCountry = {
        ...state.currenciesByCountry,
        [countryCode]: data || [],
      };
    },

    // STATES BY COUNTRY
    getStatesByCountrySuccess(state, action) {
      state.isLoading = false;
      const { countryCode, data } = action.payload;
      state.statesByCountry = {
        ...state.statesByCountry,
        [countryCode]: data || [],
      };
    },

    // CITIES BY STATE
    getCitiesByStateSuccess(state, action) {
      state.isLoading = false;
      const { stateId, data } = action.payload;
      state.citiesByState = {
        ...state.citiesByState,
        [stateId]: data || [],
      };
    },

    // CITIES BY COUNTRY
    getCitiesByCountrySuccess(state, action) {
      state.isLoading = false;
      const { countryCode, data } = action.payload;
      state.citiesByCountry = {
        ...state.citiesByCountry,
        [countryCode]: data || [],
      };
    },

    // ENUM LISTS
    getGendersSuccess(state, action) {
      state.isLoading = false;
      state.genders = action.payload || [];
    },

    getTypeDocsSuccess(state, action) {
      state.isLoading = false;
      state.typeDocs = action.payload || [];
    },

    getRelationshipsSuccess(state, action) {
      state.isLoading = false;
      state.relationships = action.payload || [];
    },

    getPurposesSuccess(state, action) {
      state.isLoading = false;
      state.purposes = action.payload || [];
    },

    getMaritalsSuccess(state, action) {
      state.isLoading = false;
      state.maritals = action.payload || [];
    },

    getTypeBanksSuccess(state, action) {
      state.isLoading = false;
      state.typeBanks = action.payload || [];
    },

    getTypeSentsSuccess(state, action) {
      state.isLoading = false;
      state.typeSents = action.payload || [];
    },

    getCalcSentsSuccess(state, action) {
      state.isLoading = false;
      state.calcSents = action.payload || [];
    },
  },
});

export default slice.reducer;

export const { startLoading, stopLoading, hasError } = slice.actions;

export function getCountries() {
  return async () => {
    dispatch(slice.actions.startLoading());
    try {
      const response = await axios.get(`${REMESAS_BASE}/countries`);
      dispatch(slice.actions.getCountriesSuccess(response.data));
    } catch (error) {
      dispatch(slice.actions.hasError(error));
    }
  };
}

export function getCurrenciesByCountry(countryCode, typeSent) {
  return async () => {
    if (!countryCode) return;
    if (!typeSent) return;
    dispatch(slice.actions.startLoading());
    try {
      const response = await axios.get(
        `${REMESAS_BASE}/countries/${countryCode}/currencies?typeSent=${typeSent}`
      );
      dispatch(
        slice.actions.getCurrenciesByCountrySuccess({
          countryCode,
          data: response.data,
        })
      );
    } catch (error) {
      dispatch(slice.actions.hasError(error));
    }
  };
}

