export async function sendOrderApi(payload) {
  try {
    const res = await axios.post(`${REMESAS_BASE}/send-order`, payload);
    return res.data;
  } catch (error) {
    const data = error.response?.data;

    const apiError = {
      code:
        data?.code ||
        (error.message === "Network Error"
          ? "NETWORK_ERROR"
          : "UNEXPECTED_ERROR"),
      message:
        data?.message ||
        data?.detail ||
        (error.message === "Network Error"
          ? "Network error, please check your connection."
          : "Unexpected error."),
      errors: data?.errors || null,
      status: error.response?.status,
    };

    throw apiError;
  }
}
